// Faction (阵营) index for the Red Alert unit banks.
//
// `redalert-sentences.ts` is generated by the scraper scripts, so faction data
// lives here as a hand-authored companion source (same pattern as the other
// curated banks): the scrapers keep writing sentences, this file keeps saying
// which faction each unit belongs to. Unit names must match the `unit` field in
// redalert-sentences.ts exactly.
//
// RA2 (含尤复的复仇 Yuri's Revenge) → Allied / Soviet / Yuri
// RA3 (含起义时刻 Uprising)        → Empire / Allied / Soviet

import { raSentencesByUnit, type RAGame, type RAUnitSentences } from './redalert-sentences';

export type RAFaction = 'Allied' | 'Soviet' | 'Yuri' | 'Empire' | 'Other';

export interface RAFactionMeta {
  /** English name as it appears in the source material. */
  en: string;
  /** Chinese name shown in the UI. */
  zh: string;
  /** Accent colour for the faction dot / chip. */
  color: string;
}

export const RA_FACTION_META: Record<RAFaction, RAFactionMeta> = {
  Allied: { en: 'Allied', zh: '盟军', color: '#3B6FD4' },
  Soviet: { en: 'Soviet', zh: '苏联', color: '#C4473A' },
  Yuri: { en: 'Yuri', zh: '尤里', color: '#7A4FC4' },
  Empire: { en: 'Empire', zh: '旭日帝国', color: '#C9821E' },
  Other: { en: 'Other', zh: '其他', color: '#8A8D9E' },
};

/** Display order of the factions inside each game. */
export const RA_GAME_FACTIONS: Record<RAGame, RAFaction[]> = {
  RA2: ['Allied', 'Soviet', 'Yuri'],
  RA3: ['Empire', 'Allied', 'Soviet'],
};

