/** Faction of a single unit. Returns `undefined` when the unit is not indexed. */
export function unitFaction(game: RAGame, unit: string): RAFaction | undefined {
  return (game === 'RA2' ? RA2_UNIT_FACTIONS : RA3_UNIT_FACTIONS)[unit];
}

export interface RAFactionGroup {
  faction: RAFaction;
  /** English faction name. */
  en: string;
  /** Chinese faction name (UI label). */
  zh: string;
  /** Accent colour. */
  color: string;
  /** Units of this faction, in the canonical browse order. */
  units: RAUnitSentences[];
  /** Total sentences across the group. */
  sentenceCount: number;
}

/**
 * Units of one game grouped by faction, in `RA_GAME_FACTIONS` order.
 * Units missing from the faction tables are never dropped — they end up in the
 * trailing `Other` group so the browse page always shows the whole roster.
 */
export function raUnitsByFaction(game: RAGame): RAFactionGroup[] {
  const buckets = new Map<RAFaction, RAUnitSentences[]>();
  const unindexed: RAUnitSentences[] = [];
  for (const f of RA_GAME_FACTIONS[game]) buckets.set(f, []);
  for (const u of raSentencesByUnit()) {
    if (u.game !== game) continue;
    const f = unitFaction(game, u.unit);
    if (f) buckets.get(f)!.push(u);
    else unindexed.push(u);
  }

  const groups: RAFactionGroup[] = [];
  for (const f of RA_GAME_FACTIONS[game]) {
    const units = buckets.get(f)!;
    if (units.length) groups.push(toGroup(f, units));
  }
  if (unindexed.length) groups.push(toGroup('Other', unindexed));
  return groups;
}

function toGroup(faction: RAFaction, units: RAUnitSentences[]): RAFactionGroup {
  const meta = RA_FACTION_META[faction];
  return {
    faction,
    en: meta.en,
    zh: meta.zh,
    color: meta.color,
    units,
    sentenceCount: units.reduce((n, u) => n + u.sentences.length, 0),
  };
}
